const email = $json;
const headers = email.headers || {};
const header = name => headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()] ?? '';
const address = value => {
  if (typeof value === 'string') return (value.match(/<([^>]+)>/)?.[1] || value).trim().toLowerCase();
  const first = value?.value?.[0] || value?.[0] || value;
  return String(first?.address || first?.email || '').trim().toLowerCase();
};
const sender = address(email.from || header('from'));
const subject = String(email.subject || header('subject') || '').trim();
const messageId = String(email.messageId || email.messageID || header('message-id') || '').trim();
const explicitReply = String(email.inReplyTo || header('in-reply-to') || '').trim();
const references = String(email.references || header('references') || '');
const rawBody = String(email.textPlain || email.text || email.html || email.textHtml || '');
const bounceSignals = `${sender} ${subject} ${rawBody.slice(0, 2000)}`.toLowerCase();
const isBounce = /(mailer-daemon|postmaster|delivery status notification|undeliverable|returned mail|mail delivery failed|recipient address rejected)/.test(bounceSignals);
const dsnOriginal = rawBody.match(/(?:Original-Message-ID|X-Original-Message-ID):\s*(<[^<>\s]+@[^<>\s]+>)/i)?.[1] || '';
const referenceIds = `${explicitReply} ${references}`.match(/<[^<>\s]+@[^<>\s]+>/g) || [];
const outboundMessageId = explicitReply || dsnOriginal || referenceIds.find(id => id !== messageId) || '';
let body = rawBody.replace(/\r/g, '').split(/\nOn .+wrote:\n|\nFrom:.+\nSent:.+\n/i)[0];
body = body.replace(/\n>.*$/gm, '').replace(/\n-- \n[\s\S]*$/, '').replace(/\n{3,}/g, '\n\n').trim().slice(0, 8000);
const received = new Date(email.date || email.receivedAt || Date.now());
if (!sender || !messageId || !body || Number.isNaN(received.getTime())) throw new Error('Inbound email is missing sender, Message-ID, usable text, or a valid date.');
return { json: { sender, subject, message_id: messageId, in_reply_to: outboundMessageId, received_at: received.toISOString(), body, is_bounce: isBounce, hard_bounce: isBounce && !/(mailbox full|temporar|try again|greylist)/.test(bounceSignals) } };

const inbound = $('Normalize and sanitize inbound email').item.json;
const result = $json.body ?? $json.data ?? $json.result ?? $json;
const candidates = Array.isArray(result.candidates) ? result.candidates : [];
const exactEnough = candidates.length === 1 && (!inbound.is_bounce || result.match_type === 'message_id');
if (!exactEnough) {
  const reason = inbound.is_bounce && result.match_type !== 'message_id'
    ? `Bounce has no exact outbound Message-ID match; ${candidates.length} sender candidates found.`
    : `Inbound email has ${candidates.length} Odoo candidates; manual matching is required.`;
  return { json: { ...inbound, matched: false, lead_id: 0, match_type: result.match_type || 'none', candidate_ids: candidates.map(candidate => candidate.id), review_reason: reason } };
}
return { json: { ...inbound, matched: true, lead_id: candidates[0].id, match_type: result.match_type, suppressed: Boolean(candidates[0].ggd_do_not_contact) } };

