let analysis = $json.output ?? $json.response ?? $json.text ?? $json;
if (typeof analysis === 'string') { const match = analysis.match(/\{[\s\S]*\}/); if (!match) throw new Error('Reply analysis was not JSON.'); analysis = JSON.parse(match[0]); }
const inbound = $('Require one unambiguous match').item.json;
const categories = ['interested','meeting','information','objection','referral','not_interested','out_of_office','unsubscribe','unclear'];
if (!categories.includes(analysis.category) || !analysis.summary || !analysis.suggested_next_action || typeof analysis.confidence !== 'number' || analysis.confidence < 0 || analysis.confidence > 1) throw new Error(`Reply ${inbound.message_id} failed structured validation.`);
return { json: { ...inbound, analysis } };
